impl.select_study_queue:
def select_study_queue(
    cards: tuple[Card, ...],
    today: date,
    settings: SchedulerSettings,
) -> StudyQueue:
    learning_cards = tuple(
        sorted(
            (card for card in cards if is_due_learning(card, today)),
            key=lambda card: (card.due_date, card.id),
        )
    )

    review_cards = tuple(
        sorted(
            (card for card in cards if is_due_review(card, today)),
            key=lambda card: (-overdue_priority(card, today), card.due_date, card.id),
        )[:max(settings.daily_review_limit, 0)]
    )

    new_cards = tuple(
        sorted(
            (card for card in cards if is_due_new(card, today)),
            key=lambda card: (card.due_date, card.id),
        )[:max(settings.daily_new_limit, 0)]
    )

    return StudyQueue(
        learning_cards=learning_cards,
        review_cards=review_cards,
        new_cards=new_cards,
    )

impl.is_leech:
def is_leech(card: Card, settings: SchedulerSettings) -> bool:
    if settings.leech_threshold <= 0:
        return False
    return card.lapses >= settings.leech_threshold

impl.suspend_leech:
def suspend_leech(card: Card, settings: SchedulerSettings) -> Card:
    if not is_leech(card, settings):
        return card
    return dataclasses.replace(card, state=CardState.SUSPENDED)

impl.grade_card:
def grade_card(
    card: Card,
    grade: Grade,
    reviewed_at: dt,
    seconds: int,
    settings: SchedulerSettings,
) -> Card:
    if card.state is CardState.SUSPENDED:
        return card

    today = reviewed_at.date()

    if card.state in (CardState.NEW, CardState.LEARNING):
        scheduled = schedule_new_or_learning(card, grade, today, settings)
    else:
        scheduled = schedule_review(card, grade, today, settings)

    scheduled = suspend_leech(scheduled, settings)

    event = ReviewEvent(
        card_id=card.id,
        reviewed_at=reviewed_at,
        grade=grade,
        seconds=max(seconds, 0),
        state_before=card.state,
    )
    return dataclasses.replace(scheduled, history=scheduled.history + (event,))

impl.bury_siblings:
def bury_siblings(
    cards: tuple[Card, ...],
    reviewed_card_id: str,
    today: date,
) -> tuple[Card, ...]:
    reviewed_card = next((card for card in cards if card.id == reviewed_card_id), None)
    if reviewed_card is None:
        return cards

    return tuple(
        dataclasses.replace(card, buried_until=today)
        if (
            card.id != reviewed_card_id
            and card.note_id == reviewed_card.note_id
            and card.state != CardState.SUSPENDED
            and (card.buried_until is None or card.buried_until < today)
        )
        else card
        for card in cards
    )

impl.current_streak:
def current_streak(cards: tuple[Card, ...], today: date) -> int:
    reviewed_dates = {
        event.reviewed_at.date()
        for card in cards
        for event in card.history
    }

    streak = 0
    current_date = today
    while current_date in reviewed_dates:
        streak += 1
        current_date -= timedelta(days=1)

    return streak

impl.grade_review:
def grade_review(
    card_id: str,
    grade: Grade,
    reviewed_at: dt,
    seconds: int,
    settings: SchedulerSettings,
):
    repository = yield from need(CardRepository)
    card = repository.get_card(card_id)

    if card is None:
        return (yield from throw(CardNotFound(card_id)))

    graded = grade_card(card, grade, reviewed_at, seconds, settings)
    repository.save_card(graded)

    all_cards = repository.list_cards()
    buried_cards = bury_siblings(all_cards, card_id, reviewed_at.date())
    originals = {existing.id: existing for existing in all_cards}

    for buried_card in buried_cards:
        if buried_card.id != card_id and buried_card != originals[buried_card.id]:
            repository.save_card(buried_card)

    return graded

